#!/usr/bin/env python3
"""Current conservative coverage. Source review packets stay immutable."""
from pathlib import Path
import json,re
r=Path(__file__).resolve().parent.parent
cards=json.loads((r/'PIPELINE/design_v3/PLAYER_EVIDENCE_39.json').read_text())
base=(r/'docs/COVERAGE_R06.md').read_text()
sections=re.split(r'\n## \d+\. ',base)[1:];assert len(sections)==39
updates={29:'R10: три возрастных силуэта и обратимые боковые формы; временной формы героя пока нет.',38:'R10: одна ручная фантастическая линия Пороговика с новым телом/приёмом/родословной, родители сохранены. Это не fusion и не универсальное скрещивание.',7:'R07: короткие главы мастера и сцены дома; R09: два индивидуальных участника и совместное открытие.',12:'R07: восстановление среды и спокойное знакомство с Мохокрылом. Полной диагностики/лечения нет.',18:'R07: три грядки, два растения, припасы и рост от новых открытий. Свободная жизнь фермы не реализована.',22:'R07–R09: ограниченный журнал реальных участников; родословная сохранена. Это не полноценная память всех NPC.',34:'R09: ведущий и резерв имеют индивидуальные UID, три сохранённых состава. Транспорта нет.',37:'R07: четвёртый вид Мохокрыл; R09: один изученный echo и три сохранённых состава, совместное открытие. R10: возрастные модели и две боковые формы с заменой варианта приёма. R11: малые разные маршруты и обход стен. Большие регионы и расширенный каталог открыты.',39:'R09: совместное открытие обучает одному конечному резонансу, три сохраняемых состава. Это НЕ fusion; исходные особи не расходуются.'}
for i in [3,5,6,8,13,17,23,26,31,35]:
 updates[i]=updates.get(i,'')+' R11: разные малые планы шести областей, общая геометрия, обход препятствий и карта на полной паузе. Это не завершённый биом/песочница/все типы укрытий.'
for i in [2,5,8,15,17,23,26,35]:
 updates[i]=updates.get(i,'')+' R12: три новых оригинальных хранителя, закреплённые предупреждения, окно ответа; разрыв волны и обрезка новых линейных атак камнем. Человеческая сложность и художественная приёмка открыты.'
for i in [2,5,6,9]:
 updates[i]=updates.get(i,'')+' R13: направленный крюк-контратака в окно восстановления, траектория/подсказка на старой кнопке и проверка пути. Это не доказанный поток или полный боевой комплект.'
lines=['# MECHANICS_COVERAGE — текущая сверка R13','','Автогенерация из сохранённого исследования v3 и фактического COVERAGE_R06 с явными дополнениями R07–R13. Новые внешние отзывы не изучались. Ни одна исходная игра не перенесена целиком; достоинства — выбранные свидетельства, не мнение большинства. Остаток каждой строки остаётся открытым даже при наличии небольшой адаптации. Общий объём — SCOPE_REGISTER.md. Дополнительные циклы: 0/10.','']
for card,sec in zip(cards,sections):
 i=card['index'];exists=re.search(r'\*\*Реально доступно у нас:\*\* (.*)',sec).group(1);missing=re.search(r'\*\*Открыто, не считать реализованным:\*\* (.*)',sec).group(1)
 if i==39:missing='Fusion/синтез, более глубокое визуальное авторство и движки и разные задачи; резонанс и составы реализованы лишь в начальном виде.'
 lines += [f"## {i:02d}. {card['game']} — частичная адаптация, не закрыто",'',f"**Особенно ценят по выбранным отзывам:** {card['especially_valued']}",f"**Что мешает:** {card['flow_breaker']}",f'**Основа R06:** {exists}',f"**Уточнение сейчас:** {updates.get(i,'См. STATUS_R07/R08/R09/R10/R11/R12/R13; исходный принцип не считается завершённым.')}",f'**Открыто:** {missing}']
 refs=[x['url'] for x in card.get('references',[]) if 'url' in x]
 if refs:lines.append('Свидетельства: '+' '.join(f'[^'+x+']' for x in refs[:3]))
 lines.append('')
(r/'docs/MECHANICS_COVERAGE.md').write_text('\n'.join(lines).rstrip()+'\n');print('39 source cards updated conservatively; none closed')
